// generar_269_paseos_mes_calendario.js
// CHIQUI Entre Señales — Paseos por mes calendario + comparación
// mensual + indicadores
//
// BUG CORREGIDO: la tarjeta decía "Paseo este mes" pero sumaba los
// últimos 30 días móviles. Por eso el total BAJABA con los días (42h
// hace dos días, 37h hoy): al avanzar la ventana iba soltando
// registros por atrás. Ahora suma del día 1 del mes hasta hoy, así
// solo puede crecer dentro del mes y parte de cero el día 1.
//
// Cambios:
//
// 1) "Paseo en <mes>" — total del mes calendario en curso, con el
//    nombre del mes explícito para que no quede duda de qué período
//    es. Debajo, comparación con el mes anterior cuando ese mes tuvo
//    registros ("↑ 3h 20m vs. mes anterior").
//
// 2) 🔥 RACHA — sin cambios de lógica: sigue siendo días consecutivos
//    con al menos un paseo y NO se reinicia el día 1. Además se
//    corrigió un límite silencioso: antes se calculaba sobre los 30
//    días cargados y por lo tanto no podía pasar de 30. Ahora usa el
//    historial de 6 meses y admite rachas de hasta 200 días.
//
// 3) GRÁFICO MENSUAL en lugar de "últimos 7 días": barras con el
//    tiempo total de paseo de los últimos 6 meses calendario, con el
//    valor sobre cada barra. El mes en curso va en canela y con una
//    nota ("todavía no termina"), porque compararlo a medias contra
//    meses completos sin avisar sería engañoso.
//
// 4) DETALLE DEL MES — nuevo bloque con:
//    · Días con paseo (ej. "18 de 24")
//    · Promedio por salida
//    · Promedio diario del mes
//    · Día más largo, con su fecha
//
//    NOTA SOBRE EL DATO: el registro diario guarda UN paseo por día,
//    no salidas individuales. Por eso el indicador dice "Días con
//    paseo" y no "Cantidad de paseos", y el promedio es por día con
//    paseo. Etiquetarlo de otro modo prometería una precisión que el
//    modelo de datos hoy no tiene. Si más adelante quieres contar
//    salidas por separado, habría que permitir varios paseos por día
//    en el registro.
//
// Técnico: se agrega una consulta liviana (fecha, paseo,
// paseo_minutos_exactos) de 6 meses calendario, aparte de los 30 días
// que ya se cargaban para el resto del análisis.
//
// No hay SQL.
//
// Uso:
//   node generar_269_paseos_mes_calendario.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
